// MaxUploadSize — максимальный допустимый размер загружаемого файла в байтах.
// Значение 10 МБ выбрано как разумный лимит для типичных веб-приложений.
const MaxUploadSize = 10 * 1024 * 1024 // 10 МБ

// AllowedMIMETypes — список разрешённых MIME-типов для загрузки.
// Включены наиболее распространённые типы: изображения, PDF, текстовые файлы.
var AllowedMIMETypes = map[string]bool{
	"image/jpeg": true,
	"image/png":  true,
	"image/gif":  true,
	"image/webp": true,
	"application/pdf": true,
	"text/plain":      true,
	"application/json": true,
}

// UploadHandler — HTTP-обработчик для загрузки файлов.
// Принимает POST-запрос с multipart/form-data, проверяет размер и MIME-тип файла,
// сохраняет его на диск в указанную директорию.
//
// Параметры:
//   - uploadDir: директория, куда будут сохраняться загруженные файлы.
//     Директория должна существовать и быть доступна для записи.
//
// Возвращает:
//   - http.HandlerFunc, готовый к использованию в маршрутизаторе.
func UploadHandler(uploadDir string) http.HandlerFunc {
	// Проверяем, что директория существует и доступна для записи.
	// Если нет — логируем ошибку и возвращаем обработчик, который всегда будет
	// возвращать 500 Internal Server Error. Это позволяет избежать паники при
	// инициализации приложения.
	if _, err := os.Stat(uploadDir); os.IsNotExist(err) {
		log.Printf("Ошибка: директория для загрузки не найдена: %s", uploadDir)
		return func(w http.ResponseWriter, r *http.Request) {
			http.Error(w, "Внутренняя ошибка сервера", http.StatusInternalServerError)
		}
	}

	// Возвращаем обработчик, который будет вызываться при каждом запросе.
	return func(w http.ResponseWriter, r *http.Request) {
		// Разрешаем только POST-метод. Все остальные методы (GET, PUT и т.д.)
		// будут отклонены с кодом 405 Method Not Allowed.
		if r.Method != http.MethodPost {
			http.Error(w, "Метод не поддерживается. Используйте POST.", http.StatusMethodNotAllowed)
			return
		}

		// Ограничиваем максимальный размер тела запроса.
		// Это защита от атак типа "загрузка огромного файла", которая может
		// исчерпать память сервера. Метод MaxBytesReader оборачивает тело запроса
		// и возвращает ошибку, если превышен лимит.
		r.Body = http.MaxBytesReader(w, r.Body, MaxUploadSize)

