/// <summary>
/// Выполняет асинхронную операцию с повторными попытками при возникновении ошибок HTTP.
/// Использует экспоненциальную задержку между попытками для снижения нагрузки на сервер.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число, которую нужно выполнить.</param>
/// <param name="attempts">Максимальное количество попыток выполнения операции.</param>
/// <returns>Результат выполнения операции (целое число).</returns>
/// <exception cref="InvalidOperationException">Возникает, если все попытки исчерпаны и операция не удалась.</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения заданного количества попыток
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить переданную асинхронную операцию
