// Функция worker представляет собой функцию-работник, которая обрабатывает задачи из канала jobs.
// Она принимает:
//   - jobs: канал для получения задач (Job)
//   - results: канал для отправки результатов обработки (Result)
//   - wg: указатель на WaitGroup для синхронизации завершения всех работников
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Деферированный вызов wg.Done() гарантирует, что после завершения работы
    // данного воркера будет уменьшен счетчик WaitGroup, что позволит главному
    // потоку узнать о завершении всех работников.
    defer wg.Done()

    // Цикл for range jobs читает задачи из канала jobs до его закрытия.
    // Каждая задача j обрабатывается последовательно в рамках этого воркера.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Она возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке возникла ошибка, логируем её с указанием ID задачи
        // и пропускаем эту задачу, не отправляя результат в канал results.
        if err != nil {
            log.Printf("job %d: %v", j.ID, err)
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в канал results.
        // Это блокирующая операция: воркер будет ждать, пока другой поток
        // не прочитает результат из канала.
        results <- r
    }
}
