/**
 * Функция для создания дебаунс-обёртки вокруг переданной функции.
 *
 * @param fn - Функция, которую нужно обернуть.
 * @param ms - Задержка в миллисекундах, после которой функция будет вызвана.
 * @returns Обёрнутая функция, которая откладывает выполнение оригинальной функции
 *          до тех пор, пока не прекратятся вызовы в течение заданного времени.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Используется для отмены предыдущего таймера при новом вызове.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и оригинальная.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен, отменяем его.
    // Это позволяет сбросить отсчёт времени при каждом новом вызове.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который вызовет оригинальную функцию
    // через ms миллисекунд, передавая ей текущие аргументы.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

