 * @param K Тип ключа карты.
 * @param V Тип значения карты.
 * @param key Ключ, по которому нужно получить или создать значение.
 * @param factory Лямбда-функция, которая создает новое значение, если его нет в карте.
 * @return Значение, связанное с ключом (существующее или только что созданное).
 */
fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Обеспечивает потокобезопасность: блокирует доступ к карте на время выполнения блока,
    // чтобы избежать гонок при одновременном чтении/записи из разных потоков.
    synchronized(this) {
        // Пытается получить значение по ключу.
        // Если значение отсутствует, `this[key]` вернет null.
        this[key]
        // Если значение отсутствует (null), то:
        // 1. Вызывается `factory()` для создания нового значения.
        // 2. `also { this[key] = it }` сохраняет созданное значение в карту под ключом `key`.
        // 3. Возвращает созданное значение.
        // Если значение уже существует, оно просто возвращается без вызова фабрики.
        ?: factory().also { this[key] = it }
    }
